-- Read-only installation verification. Existing marker routines and business records stay unchanged.
begin;
do $$begin
 if to_regprocedure('public.get_installation_component_engine_version()')is not null then
  if public.get_installation_component_engine_version()is distinct from '20261107-installation-components-1'then raise exception 'Existing component verification engine integrity differs.';end if;
 end if;
end;$$;
create schema if not exists greenloop_private;
create table if not exists greenloop_private.installation_component_engine(identity text primary key,hash text not null);
alter table greenloop_private.installation_component_engine enable row level security;
revoke all on greenloop_private.installation_component_engine from public,anon,authenticated;
