create or replace function greenloop_private.vc2_node(p_name text,p_values jsonb,p_path text[],p_catalog jsonb)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare spec jsonb;f record;dep text;answer text;query text;states jsonb:=p_values;failure jsonb;
begin
 if states?p_name then return states;end if;
 if p_name=any(p_path)then raise exception 'Verification dependency cycle.'using errcode='55000';end if;
 spec:=p_catalog->'components'->p_name;
 if spec is null then raise exception 'Unreviewed verification component.'using errcode='22023';end if;
 select p.*,l.lanname into f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(format('public.%I()',p_name));
 if not found then return states||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','missing-marker','rpc',p_name,'message','Version check is not installed yet.'));end if;
 if md5(replace(replace(f.prosrc,chr(13)||chr(10),chr(10)),chr(13),chr(10)))is distinct from spec->>'hash'
 or f.pronargs<>0 or f.prorettype<>'text'::regtype or f.proretset or f.prosecdef is distinct from(spec->>'security_definer')::boolean
 or f.provolatile::text is distinct from spec->>'volatility'or f.lanname is distinct from spec->>'language'or to_jsonb(f.proconfig)is distinct from spec->'settings'
 or not has_function_privilege('anon',f.oid,'EXECUTE')or not has_function_privilege('authenticated',f.oid,'EXECUTE')then
 return states||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','changed-marker','rpc',p_name,'message','Reviewed verification definition or access changed.'));end if;
 for dep in select jsonb_array_elements_text(spec->'dependencies')loop
  if not states?dep then raise exception 'Verification dependency order changed.'using errcode='55000';end if;
  if(states->dep->>'ok')is distinct from 'true'then
   failure:=coalesce(states->dep,'{}');
   return states||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','dependency-error','rpc',p_name,'dependency_rpc',coalesce(failure->>'dependency_rpc',dep),'message','Required component failed: '||coalesce(failure->>'dependency_rpc',dep)||'. '||coalesce(failure->>'message','Integrity could not be verified.')));
  end if;
 end loop;
 if f.lanname='sql'then
  query:=f.prosrc;
  for dep in select jsonb_array_elements_text(spec->'dependencies')loop
   query:=regexp_replace(query,'(public\.)?'||dep||'\s*\(\s*\)',format('($1->%L->>''version'')',dep),'g');
  end loop;
  execute query into answer using states;
 elsif f.lanname='plpgsql'then
  -- Reviewed legacy procedural checks retain their own loops and row/ACL checks.
  execute format('select public.%I()',p_name)into answer;
 else raise exception 'Unsupported reviewed verifier language.'using errcode='55000';end if;
 return states||jsonb_build_object(p_name,case when answer is not null then jsonb_build_object('ok',true,'kind','verified','rpc',p_name,'version',answer)
 else jsonb_build_object('ok',false,'kind','changed-marker','rpc',p_name,'message','Database integrity checks did not pass.')end);
exception when others then
 return states||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','verification-error','rpc',p_name,'code',sqlstate,'message','Reviewed integrity check could not be evaluated.'));
end;$$;
revoke all on function greenloop_private.vc2_catalog(),greenloop_private.vc2_node(text,jsonb,text[],jsonb)from public,anon,authenticated;
create or replace function public.get_installation_component_engine_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$
 select case when(select count(*)=4 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.installation_component_engine)
 and exists(select 1 from pg_class where oid='greenloop_private.installation_component_engine'::regclass and relrowsecurity)
 and not has_table_privilege('anon','greenloop_private.installation_component_engine','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_table_privilege('authenticated','greenloop_private.installation_component_engine','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 and not has_function_privilege('anon','greenloop_private.vc2_catalog()','EXECUTE')and not has_function_privilege('authenticated','greenloop_private.vc2_catalog()','EXECUTE')
 and not has_function_privilege('anon','greenloop_private.vc2_node(text,jsonb,text[],jsonb)','EXECUTE')and not has_function_privilege('authenticated','greenloop_private.vc2_node(text,jsonb,text[],jsonb)','EXECUTE')
 and has_function_privilege('anon','public.get_installation_component_version(text)','EXECUTE')and has_function_privilege('authenticated','public.get_installation_component_version(text)','EXECUTE')
 then '20261107-installation-components-1'end;
$$;
create or replace function public.get_installation_component_version(p_name text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare catalog jsonb;states jsonb:='{}';required text[];name text;
begin
 if public.get_installation_component_engine_version()is distinct from '20261107-installation-components-1'then raise exception 'Component verification engine integrity check failed.'using errcode='55000';end if;
 catalog:=greenloop_private.vc2_catalog();
 if p_name is null or not(catalog->'components'?p_name)then raise exception 'Unreviewed verification component.'using errcode='22023';end if;
 with recursive needed(name)as(select p_name union select dep from needed n cross join lateral jsonb_array_elements_text(catalog->'components'->n.name->'dependencies')x(dep))select array_agg(needed.name)into required from needed;
 for name in select value from jsonb_array_elements_text(catalog->'order')where value=any(required)loop
  states:=greenloop_private.vc2_node(name,states,'{}',catalog);
 end loop;
 return jsonb_build_object('engine_version','20261107-installation-components-1','target',p_name,'evaluated_components',(select count(*)from jsonb_object_keys(states)),'result',states->p_name);
end;$$;
revoke all on function public.get_installation_component_engine_version(),public.get_installation_component_version(text)from public;
grant execute on function public.get_installation_component_engine_version(),public.get_installation_component_version(text)to anon,authenticated;
insert into greenloop_private.installation_component_engine select s,md5(pg_get_functiondef(s::regprocedure))from unnest(array['greenloop_private.vc2_catalog()','greenloop_private.vc2_node(text,jsonb,text[],jsonb)','public.get_installation_component_engine_version()','public.get_installation_component_version(text)'])s on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_installation_component_engine_version()is distinct from '20261107-installation-components-1'then raise exception 'Component verifier failed its own integrity checks. Installation rolled back.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_installation_component_engine_version()as installed_installation_component_engine_version;
